// Title: Export numbers larger than 1,000,000 to HTML without scientific notation using Aspose.Cells for .NET (C#)
// Common Searches: Aspose.Cells C# export million‑plus values to HTML with plain decimal format | prevent exponential notation in HTML output generated by Aspose.Cells | set cell style for large numbers when saving workbook as HTML in .NET | verify that Aspose.Cells HTML export does not use scientific notation | configure HtmlSaveOptions to keep large numbers readable in HTML
// Tags: Aspose.Cells HTML export numeric format | C# set cell style plain decimal Aspose.Cells | HtmlSaveOptions suppress scientific notation | large number representation in HTML workbook | verify HTML output for exponential notation Aspose.Cells

using System;
using System.IO;
using Aspose.Cells;

namespace AsposeCellsHtmlExportTest
{
    // The example creates a workbook, writes values greater than one million to cells, applies integer and two‑decimal styles to force plain decimal display, configures HtmlSaveOptions, saves the workbook as an HTML file, and then checks the generated HTML to ensure no scientific (exponential) notation appears.
    class Program
    {
        static void Main()
        {
            try
            {
                // Create a new workbook and get the first worksheet
                Workbook workbook = new Workbook();
                Worksheet sheet = workbook.Worksheets[0];

                // Insert large numeric values (> 1,000,000)
                sheet.Cells["A1"].PutValue(1234567);          // 1,234,567
                sheet.Cells["A2"].PutValue(9876543.21);       // 9,876,543.21

                // Apply a number format that forces plain decimal representation (no scientific notation)
                Style plainStyle = workbook.CreateStyle();
                plainStyle.Number = 0; // "0" format – integer without grouping

                Style decimalStyle = workbook.CreateStyle();
                decimalStyle.Number = 2; // "0.00" format – two decimal places

                // Assign styles to the cells
                sheet.Cells["A1"].SetStyle(plainStyle);
                sheet.Cells["A2"].SetStyle(decimalStyle);

                // Configure HTML save options
                HtmlSaveOptions htmlOptions = new HtmlSaveOptions(SaveFormat.Html);
                // ExportImagesAsBase64 is optional here; kept for completeness
                htmlOptions.ExportImagesAsBase64 = true;

                // Define output HTML file path
                string htmlPath = "LargeNumbersExport.html";

                // Save the workbook as HTML
                workbook.Save(htmlPath, htmlOptions);

                // Verify that the exported HTML does not contain exponential notation
                if (File.Exists(htmlPath))
                {
                    string htmlContent = File.ReadAllText(htmlPath);
                    bool containsExponential = htmlContent.Contains("E+") ||
                                               htmlContent.Contains("e+") ||
                                               htmlContent.Contains("E-") ||
                                               htmlContent.Contains("e-");

                    Console.WriteLine("HTML export completed: " + htmlPath);
                    Console.WriteLine("Exponential notation present? " + (containsExponential ? "Yes" : "No"));
                }
                else
                {
                    Console.WriteLine("Failed to create HTML file: " + htmlPath);
                }
            }
            catch (Exception ex)
            {
                Console.WriteLine("An error occurred: " + ex.Message);
            }
        }
    }
}
